228	  // Builds the DMI bus + warmup snapshot shared by both handoff modes:
229	  // stores the bus in hybrid_dmi_bus_ and returns the snapshot for the caller
230	  // to move into its controller.
231	  auto make_handoff_snapshot(uint64_t vsim_warmup_icount)
232	    -> hybrid::MeasureStartSnapshot
233	  {
234	    hybrid_dmi_bus_ = std::make_unique<
235	      hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
236	                            PLATFORM::dmi_data_width>>(platform.dmi,
237	                                                       platform.clk.period());
238	    if (vsim_warmup_icount > 0)
239	      spdlog::info("hybrid: warmup window enabled, K={}", vsim_warmup_icount);
240	    return hybrid::MeasureStartSnapshot{vsim_warmup_icount, *hybrid_dmi_bus_};
241	  }
242	
243	  // Enables the vsim->QEMU handoff drain. After this is set, run() watches
244	  // committed PCs and on retire of a `csrw 0x7C0, *` exit-trigger drains
245	  // architectural state to `state_out_path` and returns kExitHandoffToQemu.
246	  //
247	  // When `exit_pc` is set, the trigger is populated by `add_pc_hit` (PC
248	  // mode) and the ELF scan is skipped: the binary need not contain a magic
249	  // csrwi marker. CSR mode and PC mode are mutually exclusive on a single
250	  // run -- callers pass exactly one form.
251	  void enable_hybrid_handoff(const std::string& elf_path,
252	                             const std::string& state_out_path,
253	                             std::optional<uint64_t> exit_pc = std::nullopt,
254	                             uint64_t vsim_warmup_icount = 0)
255	  {
256	    hybrid::CsrTrigger trigger;
257	    if (exit_pc) {
258	      trigger.add_pc_hit(*exit_pc, HYBRID_HANDOFF_EXIT);
259	      spdlog::info("hybrid: PC-trigger mode, exit_pc=0x{:x}", *exit_pc);
260	    } else {
261	      auto elf = LIEF::ELF::Parser::parse(elf_path);
262	      if (!elf)
263	        throw std::runtime_error(
264	          "enable_hybrid_handoff: failed to parse " + elf_path);
265	      for (const auto& seg: elf->segments()) {
266	        if (seg.type() != LIEF::ELF::SEGMENT_TYPES::PT_LOAD) continue;
267	        if ((static_cast<unsigned>(seg.flags()) & 1u) == 0u) continue;  // PF_X
268	        const auto content = seg.content();
269	        const std::span<const uint8_t> bytes{content.data(), content.size()};
270	        trigger.scan_buffer(bytes, seg.virtual_address());
271	      }
272	    }
273	
274	    auto snapshot = make_handoff_snapshot(vsim_warmup_icount);
275	    hybrid_handoff_.emplace(std::move(trigger), *hybrid_dmi_bus_,
276	                            std::move(snapshot), v_scratch_gpa());
277	    if (hybrid_input_state_)
278	      hybrid_handoff_->set_passthrough_input(*hybrid_input_state_);
279	    hybrid_state_path_ = state_out_path;
280	  }
281	
282	  // icount-trigger variant: drain after `target` committed insns retire,
283	  // regardless of PC. Sibling to enable_hybrid_handoff (which is CSR/PC). The
284	  // two modes are mutually exclusive on a single run -- callers pass at most
285	  // one. Multi-hart out of scope per F6: the trigger counts hart-0 retires.
286	  void enable_hybrid_icount_handoff(const std::string& state_out_path,
287	                                    uint64_t icount_target,
288	                                    uint64_t vsim_warmup_icount = 0)
289	  {
290	    hybrid::IcountTrigger trigger{icount_target};
291	    spdlog::info("hybrid: icount-trigger mode, target={}", icount_target);
292	
293	    auto snapshot = make_handoff_snapshot(vsim_warmup_icount);
294	    hybrid_icount_handoff_.emplace(std::move(trigger), *hybrid_dmi_bus_,
295	                                   std::move(snapshot), v_scratch_gpa());
296	    if (hybrid_input_state_)
297	      hybrid_icount_handoff_->set_passthrough_input(*hybrid_input_state_);
298	    hybrid_state_path_ = state_out_path;
299	  }
300	
301	  // cosim_roi F2 / cosim_redesign F3: drain resumable checkpoints -- every
302	  // `interval` retires, or at each explicit retire target (the last target
303	  // finishes the run). Records append to the `<handoff_out>.ckpts` stream
304	  // (concatenated hybrid_state_v1; count = filesize / sizeof). Call AFTER
305	  // enable_hybrid_handoff -- checkpoints ride the CSR/PC handoff
306	  // controller, so icount mode cannot carry them.
307	  void enable_hybrid_cosim(uint64_t interval)
308	  {
309	    spdlog::info("hybrid cosim: checkpoint every {} retires", interval);
310	    require_handoff_for_cosim();
311	    hybrid_handoff_->enable_cosim(interval, make_cosim_stream_sink());
312	  }
313	
314	  void enable_hybrid_cosim_targets(std::vector<uint64_t> targets)
315	  {
316	    spdlog::info("hybrid cosim: {} explicit checkpoint targets, finish at "
317	                 "retire {}", targets.size(), targets.back());
318	    require_handoff_for_cosim();
319	    hybrid_handoff_->enable_cosim_targets(std::move(targets),
320	                                          make_cosim_stream_sink());
321	  }
322	
323	  // cosim_redesign F4: lock-step DV mode. Boot the ELF, halt at reset,
324	  // single-step to `arm_pc` (default: the ELF entry), then drain one full
325	  // record per execution attempt into the `out_path` stream. K=0 runs
326	  // until the program exits (SimControl).
327	  void enable_cosim_lockstep(std::optional<uint64_t> arm_pc,
328	                             const std::string& out_path,
329	                             uint64_t max_records)
330	  {
331	    hybrid_dmi_bus_ = std::make_unique<
332	      hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
333	                            PLATFORM::dmi_data_width>>(platform.dmi,
334	                                                       platform.clk.period());
335	    lockstep_cfg_ = hybrid::LockstepSession::Config{
336	      .arm_pc      = arm_pc.value_or(elf_entry_),
337	      .max_records = max_records,
338	    };
339	    lockstep_out_ = out_path;
340	    spdlog::info("cosim lockstep: arm pc=0x{:x}, max records={}, out={}",
341	                 lockstep_cfg_->arm_pc, max_records, out_path);
342	  }
343	
344	private:
345	  // L26: the GUEST address of the V-register transport page -- the top page of
346	  // the mapped RAM span. The driver maps one page above --mem-size (scheme D),
347	  // so this sits just past the program's declared RAM and never collides with
348	  // its data/stack. Single source of truth handed to ResumeDriver/StateDrain.
349	  auto v_scratch_gpa() const -> uint64_t
350	  {
351	    return hybrid::v_scratch_gpa(platform.main_memory.region.base_address,
352	                                 platform.main_memory.data.size());
353	  }
354	
355	  void require_handoff_for_cosim()
356	  {
357	    if (!hybrid_handoff_)
358	      throw std::runtime_error(
359	        "enable_hybrid_cosim: requires the CSR/PC hybrid handoff "
360	        "(incompatible with --hybrid-icount)");
361	  }
362	
363	  // Record sink: V-merge from scratch RAM (same as the exit drain), then
364	  // append the record to the `path` stream. The stream is truncated here
365	  // so a re-run never carries stale records.
366	  auto make_stream_sink(const std::string& path)
367	    -> std::function<void(const hybrid_state_v1&, uint64_t)>
368	  {
369	    std::ofstream{path, std::ios::binary | std::ios::trunc};
370	    return [this, path](const hybrid_state_v1& drained, uint64_t k) {
371	      auto state = drained;
372	      if ((state.flags & HYBRID_FLAG_V) != 0u) {
373	        hybrid::read_v_from_scratch(
374	          state,
375	          std::span<const uint8_t>{platform.main_memory.data.data(),
376	                                   platform.main_memory.data.size()});
377	      }
378	      spdlog::info("hybrid cosim: record {} at pc=0x{:x}, appending to {}",
379	                   k, state.pc, path);
380	      std::ofstream f(path, std::ios::binary | std::ios::app);
381	      f.write(reinterpret_cast<const char*>(&state), sizeof(state));
382	    };
383	  }
384	
385	  auto make_cosim_stream_sink()
386	    -> std::function<void(const hybrid_state_v1&, uint64_t)>
387	  {
388	    return make_stream_sink(hybrid_state_path_ + ".ckpts");
389	  }
390	
391	  // The lock-step session replaces the main run loop entirely: every cycle
392	  // advance happens inside the DMI bus pumping. Device side effects (UART,
393	  // SimControl) still run; the stop check ends the session when the
394	  // program exits before max_records.
395	  auto run_lockstep_session() -> int
396	  {
397	    hybrid::LockstepSession session(
398	      *hybrid_dmi_bus_, *lockstep_cfg_, make_stream_sink(lockstep_out_),
399	      [this] {
400	        return platform.sim_control.exits >= 0
401	            || this->cpu.contextp()->gotFinish();
402	      },
403	      v_scratch_gpa());
404	    const uint64_t records = session.run();
405	    spdlog::info("cosim lockstep: {} record(s) written to {}", records,
406	                 lockstep_out_);
407	    return 0;
408	  }
