410	public:
411	
412	  void restore_context(const std::string& dir)
413	  {
414	    context_config.dir = dir;
415	    context_config.restore(platform, cpu);
416	  }
417	
418	  void save_context(const std::string& dir)
419	  {
420	    context_config.dir = dir;
421	    context_config.save(platform, cpu);
422	  }
423	
424	  // skip_memory_load: parse the ELF and set the reset vector, but leave
425	  // platform.main_memory untouched. Used in tier-2 hybrid resume where
426	  // QEMU 1's -kernel already populated the shared mmap; re-loading would
427	  // zero-fill the .bss tail of each PT_LOAD and destroy phase-1 writes
428	  // to static buffers. The reset vector is still set so the hart has a
429	  // valid fetch target during the post-reset cycles that precede the DMI
430	  // halt+DPC-write resume sequence.
431	  void load_elf(const std::string& path, bool skip_memory_load = false)
432	  {
433	    const auto elf = LIEF::ELF::Parser::parse(path);
434	    if (!elf) {
435	      spdlog::critical("Check if it's a valid ELF file path : {}", path);
436	      exit(1);
437	    }
438	
439	    if (!skip_memory_load)
440	      read_elf_into_memory(
441	        *elf,
442	        static_cast<xlen_t>(platform.main_memory.region.base_address),
443	        platform.main_memory.data);
444	    for (auto& rv: platform.reset_vector)
445	      rv.write(elf->entrypoint());
446	    elf_entry_ = elf->entrypoint();
447	  }
448	
449	  void set_reset_vector(size_t hart, uint64_t addr)
450	  {
451	    if (hart >= platform.reset_vector.size()) {
452	      spdlog::critical("hart {} out of range (max {})", hart,
453	                       platform.reset_vector.size() - 1);
454	      std::exit(EXIT_FAILURE);
455	    }
456	    platform.reset_vector[hart].write(addr);
457	  }
458	
459	  void load_image(const std::string& path, MEM_TYPE type)
460	  {
461	    switch (type) {
462	    case MEM_TYPE::ILM:
463	      if constexpr (requires { cpu.set_ilm({}); }) {
464	        read_binary_file(path, [this](const auto& data) { cpu.set_ilm(data); });
465	      } else {
466	        throw std::runtime_error(
467	          "CPU does not support ILM - cannot load ILM ROM image");
468	      }
469	      break;
470	
471	    case MEM_TYPE::DLM:
472	      if constexpr (requires { cpu.set_dlm({}); }) {
473	        read_binary_file(path, [this](const auto& data) { cpu.set_dlm(data); });
474	      } else {
475	        throw std::runtime_error(
476	          "CPU does not support DLM - cannot load DLM ROM image");
477	      }
478	      break;
479	
480	    case MEM_TYPE::RAM:
481	      read_binary_file(path, [this](const auto& data) {
482	        if (data.size() > platform.main_memory.data.size())
483	          throw std::runtime_error("RAM image size exceeds main memory size");
484	        std::copy(data.begin(), data.end(), platform.main_memory.data.begin());
485	      });
486	      break;
487	
488	    default:
489	      throw std::runtime_error("Unknown memory type");
490	    }
491	  }
492	
493	  void reset()
494	  {
495	    static constexpr int core_num = CPU::NDS_NHART;
496	    static constexpr int reset_val = (1 << core_num) - 1;
497	
498	    platform.resetn.write(0);
499	    auto saved = context_config;
500	    context_config = {};
501	    this->run(1);
502	    context_config = saved;
503	
504	    for (size_t i = 0; i < platform.reset_vector.size(); ++i)
505	      spdlog::info("hart {} reset vector: {:#x}", i,
506	                   (uint64_t) platform.reset_vector[i].read());
507	
508	    platform.resetn.write(reset_val);
509	
510	    if (context_config.continue_from)
511	      restore_context(context_config.dir);
512	  }
513	
514	  int run(const uint64_t max_cycles = std::numeric_limits<uint64_t>::max())
515	  {
516	    auto sa = memzeroed<struct sigaction>();
517	    sa.sa_handler = sigint_handler;
518	    sigemptyset(&sa.sa_mask);
519	
520	    auto oact = memzeroed<struct sigaction>();
521	    if (sigaction(SIGINT, &sa, &oact) == -1)
522	      perror("sigaction");
523	
524	    const auto restore_sigint = std::experimental::scope_exit{[&] {
525	      if (sigaction(SIGINT, &oact, nullptr) == -1)
526	        perror("sigaction");
527	    }};
528	
529	    // wait for debugger connections
530	    while (dtm_debug && !dtm.is_connected()) {
531	      dtm.try_accept_socket();
532	      if (ctrlc != 0) {
533	        return 130;
534	      }
535	      sleep(1);
536	    }
537	
538	    // cosim_redesign F4: the lock-step session owns all cycle advancement
539	    // (DMI pumping); the main loop below never runs.
540	    if (lockstep_cfg_) return run_lockstep_session();
541	
542	    [[maybe_unused]]
543	    bool ctx_resuming = context_config.continue_from;
544	    [[maybe_unused]]
545	    bool ctx_triggered = false;
546	
547	    for (auto n = uint64_t{0}; n < max_cycles; ++n) {
548	
549	      if (ctx_resuming) [[unlikely]] {
550	        // Pull up PLIC interrupt signal at the first cycle of the resume
551	        platform.int_trigger.write(1);
552	        ctx_resuming = false;
553	        ctx_triggered = true;
554	      }
555	
556	      sc_core::sc_start(platform.clk.period());
557	
558	      trace_.on_cycle(cpu);
559	
560	      if (hybrid_handoff_ || hybrid_icount_handoff_) [[unlikely]] {
561	        if (auto code = check_hybrid_handoff(); code) return *code;
562	      }
563	
564	      if (trace_.pipeview_wants_exit()) {
565	        spdlog::info("Pipeline viewer requested exit (Kanata loop window complete)");
566	        return 0;
567	      }
568	
569	      if (context_config.save_on_wfi && platform.wfi_signal.read() == true)
570	        [[unlikely]]
571	      {
572	        context_config.save(platform, cpu);
573	        spdlog::info("User save context");
574	        return 0;
575	      }
576	
577	      if (ctrlc != 0) {
578	        ctrlc = 0;
579	        spdlog::info("Ctrl+C PC: {:x}", get_current_pc());
580	        trace_.log_committed_pcs(cpu);
581	        return 130;
582	      }
583	
584	      if (ctx_triggered) [[unlikely]] {
585	        // Pull down the interrupt signal after 1 cycle
586	        platform.int_trigger.write(0);
587	        ctx_triggered = false;
588	      }
589	
590	      if (platform.sim_control.exits >= 0) {
591	        spdlog::info("sim_control: got exit {}, stopping",
592	                     platform.sim_control.exits);
593	        spdlog::info("Exit PC: {:x}", get_current_pc());
594	        trace_.log_committed_pcs(cpu);
595	        return platform.sim_control.exits;
596	      }
597	
598	      if (this->cpu.contextp()->gotFinish())
599	        return 0;
600	
601	      spdlog::trace("PC: {:x}", get_current_pc());
602	    }
603	    return 0;
604	  }
605	
606	  uint64_t get_current_pc()
607	  {
608	    if constexpr (requires { cpu.get_current_pc(); }) {
609	      return cpu.get_current_pc();
610	    }
611	    return std::numeric_limits<uint64_t>::max();
612	  }
613	
614	  auto check_hybrid_handoff() -> std::optional<int>
615	  {
616	    if constexpr (!requires { cpu.get_committed_pc(); }) {
617	      return std::nullopt;
618	    } else {
619	      const auto committed = cpu.get_committed_pc();
620	      if (committed.empty()) return std::nullopt;
621	      for (const auto pc: committed[0]) {
622	        auto state = std::optional<hybrid_state_v1>{};
623	        if (hybrid_handoff_)
624	          state = hybrid_handoff_->on_retire(pc);
625	        else if (hybrid_icount_handoff_)
626	          state = hybrid_icount_handoff_->on_retire(pc);
627	        if (state) {
628	          // V-register merge: the fixture's vsim-phase epilogue is expected
629	          // to have run vse8.v v0..v31 to scratch RAM before the exit
630	          // trigger fired. Read those bytes back into state.vreg[] so the
631	          // drained handoff state carries vsim's actual V values, not
632	          // QEMU 1's stale snapshot.
633	          if ((state->flags & HYBRID_FLAG_V) != 0u) {
634	            hybrid::read_v_from_scratch(
635	              *state,
636	              std::span<const uint8_t>{platform.main_memory.data.data(),
637	                                       platform.main_memory.data.size()});
638	          }
639	          spdlog::info("hybrid handoff: drained at pc=0x{:x}, writing {}",
640	                       pc, hybrid_state_path_);
641	          std::ofstream f(hybrid_state_path_, std::ios::binary);
642	          f.write(reinterpret_cast<const char*>(&*state), sizeof(*state));
643	          return hybrid::kExitHandoffToQemu;
644	        }
645	      }
646	      return std::nullopt;
647	    }
648	  }
649	
650	  void enable_waveform(const std::string& waveform_filename)
651	  {
652	    trace_.enable_waveform(cpu, waveform_filename);
653	  }
654	
655	  void enable_pc_trace(const std::string& filename)
656	  {
657	    trace_.enable_pc_trace(filename);
658	  }
659	
660	  void disable_pc_trace() { trace_.disable_pc_trace(); }
661	
662	  void enable_kanata(const std::string& filename,
663	                     const std::string& objdump_file = "",
664	                     std::optional<kanata::LoopGate> gate = std::nullopt)
665	  {
666	    trace_.enable_kanata(cpu, filename, objdump_file, gate);
667	  }
668	
669	  void enable_clarity(const std::string& filename,
670	                      const std::string& objdump_file = "",
671	                      std::optional<kanata::LoopGate> gate = std::nullopt)
672	  {
673	    trace_.enable_clarity(cpu, filename, objdump_file, gate);
674	  }
675	
676	  // Auto-derive the kanata LoopGate from the active hybrid state:
677	  //   start_pc = resume PC (from hybrid_input_state_->pc)
678	  //   end_pc   = explicit_exit_pc when set (pc-mode -- the --hybrid-exit-pc
679	  //              CLI value), otherwise the unique HYBRID_HANDOFF_EXIT PC
680	  //              scanned by the CsrTrigger (csr-mode).
681	  // Must be called AFTER apply_resume_from_qemu and enable_hybrid_handoff,
682	  // so the resume PC and the CsrTrigger are populated.
683	  void enable_kanata_roi(const std::string& filename,
684	                         const std::string& objdump_file,
685	                         std::optional<uint64_t> explicit_exit_pc)
686	  {
687	    if (!hybrid_input_state_)
688	      throw std::runtime_error(
689	        "--kanata-roi requires --resume-from-qemu (no resume PC available)");
690	    if (!hybrid_handoff_)
691	      throw std::runtime_error(
692	        "--kanata-roi requires CSR or PC trigger mode "
693	        "(incompatible with --hybrid-icount)");
694	    const auto gate = hybrid::derive_roi_kanata_gate(
695	      hybrid_handoff_->trigger(), hybrid_input_state_->pc, explicit_exit_pc);
696	    spdlog::info(
697	      "kanata-roi: window start=0x{:x} end=0x{:x} (skip=0 record=1)",
698	      gate.start_pc, gate.end_pc);
699	    trace_.enable_kanata(cpu, filename, objdump_file, gate);
700	  }
701	
702	  void disable_pipeview() { trace_.disable_pipeview(); }
703	
