  // Builds the DMI bus + warmup snapshot shared by both handoff modes:
  // stores the bus in hybrid_dmi_bus_ and returns the snapshot for the caller
  // to move into its controller.
  auto make_handoff_snapshot(uint64_t vsim_warmup_icount)
    -> hybrid::MeasureStartSnapshot
  {
    hybrid_dmi_bus_ = std::make_unique<
      hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
                            PLATFORM::dmi_data_width>>(platform.dmi,
                                                       platform.clk.period());
    if (vsim_warmup_icount > 0)
      spdlog::info("hybrid: warmup window enabled, K={}", vsim_warmup_icount);
    return hybrid::MeasureStartSnapshot{vsim_warmup_icount, *hybrid_dmi_bus_};
  }

  // Enables the vsim->QEMU handoff drain. After this is set, run() watches
  // committed PCs and on retire of a `csrw 0x7C0, *` exit-trigger drains
  // architectural state to `state_out_path` and returns kExitHandoffToQemu.
  //
  // When `exit_pc` is set, the trigger is populated by `add_pc_hit` (PC
  // mode) and the ELF scan is skipped: the binary need not contain a magic
  // csrwi marker. CSR mode and PC mode are mutually exclusive on a single
  // run -- callers pass exactly one form.
  void enable_hybrid_handoff(const std::string& elf_path,
                             const std::string& state_out_path,
                             std::optional<uint64_t> exit_pc = std::nullopt,
                             uint64_t vsim_warmup_icount = 0)
  {
    hybrid::CsrTrigger trigger;
    if (exit_pc) {
      trigger.add_pc_hit(*exit_pc, HYBRID_HANDOFF_EXIT);
      spdlog::info("hybrid: PC-trigger mode, exit_pc=0x{:x}", *exit_pc);
    } else {
      auto elf = LIEF::ELF::Parser::parse(elf_path);
      if (!elf)
        throw std::runtime_error(
          "enable_hybrid_handoff: failed to parse " + elf_path);
      for (const auto& seg: elf->segments()) {
        if (seg.type() != LIEF::ELF::SEGMENT_TYPES::PT_LOAD) continue;
        if ((static_cast<unsigned>(seg.flags()) & 1u) == 0u) continue;  // PF_X
        const auto content = seg.content();
        const std::span<const uint8_t> bytes{content.data(), content.size()};
        trigger.scan_buffer(bytes, seg.virtual_address());
      }
    }

    auto snapshot = make_handoff_snapshot(vsim_warmup_icount);
    hybrid_handoff_.emplace(std::move(trigger), *hybrid_dmi_bus_,
                            std::move(snapshot), v_scratch_gpa());
    if (hybrid_input_state_)
      hybrid_handoff_->set_passthrough_input(*hybrid_input_state_);
    hybrid_state_path_ = state_out_path;
  }

  // icount-trigger variant: drain after `target` committed insns retire,
  // regardless of PC. Sibling to enable_hybrid_handoff (which is CSR/PC). The
  // two modes are mutually exclusive on a single run -- callers pass at most
  // one. Multi-hart out of scope per F6: the trigger counts hart-0 retires.
  void enable_hybrid_icount_handoff(const std::string& state_out_path,
                                    uint64_t icount_target,
                                    uint64_t vsim_warmup_icount = 0)
  {
    hybrid::IcountTrigger trigger{icount_target};
    spdlog::info("hybrid: icount-trigger mode, target={}", icount_target);

    auto snapshot = make_handoff_snapshot(vsim_warmup_icount);
    hybrid_icount_handoff_.emplace(std::move(trigger), *hybrid_dmi_bus_,
                                   std::move(snapshot), v_scratch_gpa());
    if (hybrid_input_state_)
      hybrid_icount_handoff_->set_passthrough_input(*hybrid_input_state_);
    hybrid_state_path_ = state_out_path;
  }

  // cosim_roi F2 / cosim_redesign F3: drain resumable checkpoints -- every
  // `interval` retires, or at each explicit retire target (the last target
  // finishes the run). Records append to the `<handoff_out>.ckpts` stream
  // (concatenated hybrid_state_v1; count = filesize / sizeof). Call AFTER
  // enable_hybrid_handoff -- checkpoints ride the CSR/PC handoff
  // controller, so icount mode cannot carry them.
  void enable_hybrid_cosim(uint64_t interval)
  {
    spdlog::info("hybrid cosim: checkpoint every {} retires", interval);
    require_handoff_for_cosim();
    hybrid_handoff_->enable_cosim(interval, make_cosim_stream_sink());
  }

  void enable_hybrid_cosim_targets(std::vector<uint64_t> targets)
  {
    spdlog::info("hybrid cosim: {} explicit checkpoint targets, finish at "
                 "retire {}", targets.size(), targets.back());
    require_handoff_for_cosim();
    hybrid_handoff_->enable_cosim_targets(std::move(targets),
                                          make_cosim_stream_sink());
  }

  // cosim_redesign F4: lock-step DV mode. Boot the ELF, halt at reset,
  // single-step to `arm_pc` (default: the ELF entry), then drain one full
  // record per execution attempt into the `out_path` stream. K=0 runs
  // until the program exits (SimControl).
  void enable_cosim_lockstep(std::optional<uint64_t> arm_pc,
                             const std::string& out_path,
                             uint64_t max_records)
  {
    hybrid_dmi_bus_ = std::make_unique<
      hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
                            PLATFORM::dmi_data_width>>(platform.dmi,
                                                       platform.clk.period());
    lockstep_cfg_ = hybrid::LockstepSession::Config{
      .arm_pc      = arm_pc.value_or(elf_entry_),
      .max_records = max_records,
    };
    lockstep_out_ = out_path;
    spdlog::info("cosim lockstep: arm pc=0x{:x}, max records={}, out={}",
                 lockstep_cfg_->arm_pc, max_records, out_path);
  }

private:

