      if ((state.flags & HYBRID_FLAG_V) != 0u) {
        hybrid::read_v_from_scratch(
          state,
          std::span<const uint8_t>{platform.main_memory.data.data(),
                                   platform.main_memory.data.size()});
      }
      spdlog::info("hybrid cosim: record {} at pc=0x{:x}, appending to {}",
                   k, state.pc, path);
      std::ofstream f(path, std::ios::binary | std::ios::app);
      f.write(reinterpret_cast<const char*>(&state), sizeof(state));
    };
  }

  auto make_cosim_stream_sink()
    -> std::function<void(const hybrid_state_v1&, uint64_t)>
  {
    return make_stream_sink(hybrid_state_path_ + ".ckpts");
  }

  // The lock-step session replaces the main run loop entirely: every cycle
  // advance happens inside the DMI bus pumping. Device side effects (UART,
  // SimControl) still run; the stop check ends the session when the
  // program exits before max_records.
  auto run_lockstep_session() -> int
  {
    hybrid::LockstepSession session(
      *hybrid_dmi_bus_, *lockstep_cfg_, make_stream_sink(lockstep_out_),
      [this] {
        return platform.sim_control.exits >= 0
            || this->cpu.contextp()->gotFinish();
      },
      v_scratch_gpa());
    const uint64_t records = session.run();
    spdlog::info("cosim lockstep: {} record(s) written to {}", records,
                 lockstep_out_);
    return 0;
  }

