72	  // Built by hand (not fmt) to keep the literal {bin}/{elf}/{state_in}
73	  // placeholders out of fmt's brace parser.
74	  std::string json;
75	  json += "{\n";
76	  json += "  \"id\": \"verilator:" + cfg + "\",\n";
