226	// cosim_redesign F3: parse the --hybrid-cosim-at colon-separated retire
227	// targets. Must be strictly ascending, each >= 1.
228	static auto parse_cosim_targets(const std::string& spec)
229	  -> std::vector<uint64_t>
230	{
231	  std::vector<uint64_t> targets;
232	  std::size_t pos = 0;
233	  while (pos <= spec.size()) {
234	    const auto colon = spec.find(':', pos);
235	    const auto tok = spec.substr(
236	      pos, colon == std::string::npos ? std::string::npos : colon - pos);
237	    try {
238	      std::size_t used = 0;
239	      const uint64_t v = std::stoull(tok, &used, 0);
240	      if (used != tok.size() || v == 0) throw std::invalid_argument(tok);
241	      targets.push_back(v);
242	    } catch (...) {
243	      throw std::runtime_error("--hybrid-cosim-at: bad target '" + tok
244	                               + "' in '" + spec + "'");
245	    }
246	    if (colon == std::string::npos) break;
247	    pos = colon + 1;
248	  }
249	  for (std::size_t i = 1; i < targets.size(); ++i)
250	    if (targets[i] <= targets[i - 1])
251	      throw std::runtime_error(
252	        "--hybrid-cosim-at: targets must be strictly ascending: " + spec);
253	  return targets;
254	}
