394	    p.longopt("shared-mem-path",
395	              [&](const std::string_view s) { args.shared_mem_path = s; });
396	    // Shared uint64 longopt handler: parse with 0x/0 prefixes, else throw a
397	    // uniform "invalid --<flag>". Replaces six identical try/catch blocks.
398	    auto u64_opt = [](const char* flag, auto& dest) {
399	      return [flag, &dest](std::string_view s) {
400	        try {
401	          dest = std::stoull(std::string{s}, nullptr, 0);
402	        } catch (...) {
403	          throw std::runtime_error(std::string{"invalid --"} + flag + ": "
404	                                   + std::string{s});
405	        }
406	      };
407	    };
408	    p.longopt("shared-mem-size", u64_opt("shared-mem-size", args.shared_mem_size));
409	    p.longopt("shared-mem-base", u64_opt("shared-mem-base", args.shared_mem_base));
