459	  const auto time_resolution = sc_core::sc_get_time_resolution();
460	  spdlog::debug("Using time resolution: {}", time_resolution.to_string());
461	
462	  std::optional<MmapBacking> shared_ram;
463	  if (!args.shared_mem_path.empty()) {
464	    if (args.shared_mem_size == 0)
465	      throw std::runtime_error(
466	        "--shared-mem-path requires --shared-mem-size > 0");
467	    shared_ram.emplace(args.shared_mem_path, args.shared_mem_size);
468	  } else if (args.shared_mem_size != 0) {
