514	    if (!args.kanata_file.empty() && !args.clarity_file.empty())
515	      throw std::runtime_error("--kanata and --clarity are mutually exclusive");
516	
517	    std::optional<kanata::LoopGate> loop_gate;
518	    if (args.kanata_loop_start.has_value()
519	        != args.kanata_loop_end.has_value())
520	      throw std::runtime_error(
521	        "--kanata-loop-start and --kanata-loop-end must be specified together");
522	    if (args.kanata_loop_start.has_value()) {
523	      if (args.kanata_file.empty() && args.clarity_file.empty())
524	        throw std::runtime_error(
525	          "--kanata-loop-* requires --kanata or --clarity");
526	      if (args.kanata_loop_record == 0)
527	        throw std::runtime_error("--kanata-loop-record must be >= 1");
528	      loop_gate = kanata::LoopGate{*args.kanata_loop_start,
529	                                   *args.kanata_loop_end,
530	                                   args.kanata_loop_skip,
531	                                   args.kanata_loop_record};
532	    }
