534	    // --kanata-roi defers kanata enable until after resume + handoff setup so
535	    // the gate can be auto-derived from the resumed PC + CsrTrigger / exit PC.
536	    if (args.kanata_roi) {
537	      if (args.kanata_file.empty())
538	        throw std::runtime_error("--kanata-roi requires --kanata <file>");
539	      if (loop_gate)
540	        throw std::runtime_error(
541	          "--kanata-roi and --kanata-loop-* are mutually exclusive");
542	      if (!args.clarity_file.empty())
543	        throw std::runtime_error("--kanata-roi is not supported with --clarity");
544	      if (args.hybrid_icount)
