559	    // In tier-2 hybrid resume, QEMU 1 already loaded the ELF into the
560	    // shared mmap. Re-loading would `std::fill_n(memsz - filesz, 0)` over
561	    // each PT_LOAD's .bss tail, wiping phase-1 writes to static buffers.
562	    // Still parse the ELF to set the reset vector -- between sim.reset()
563	    // and apply_resume_from_qemu's DMI halt, the hart fetches one or two
564	    // instructions from the reset vector; if that address is unmapped
565	    // the bus errors leave the hart in a state the resume cannot recover.
566	    const bool elf_already_in_shared_mmap =
567	      !args.resume_from_qemu.empty() && !args.shared_mem_path.empty();
