609	    sim.reset();
610	
611	    if (!args.resume_from_qemu.empty())
612	      sim.apply_resume_from_qemu(args.resume_from_qemu);
613	
614	    if (args.hybrid_enter_pc)
615	      spdlog::warn("--hybrid-enter-pc=0x{:x} ignored: entry trigger is "
616	                   "QEMU's job (use plugin enter_pc= arg)",
617	                   *args.hybrid_enter_pc);
