619	    if (!args.handoff_out.empty()) {
620	      if (args.hybrid_icount && args.hybrid_exit_pc)
621	        throw std::runtime_error(
622	          "--hybrid-icount and --hybrid-exit-pc are mutually exclusive");
623	      if (args.hybrid_icount)
624	        sim.enable_hybrid_icount_handoff(args.handoff_out,
625	                                         *args.hybrid_icount,
626	                                         args.vsim_warmup_icount);
627	      else
628	        sim.enable_hybrid_handoff(args.elf_file, args.handoff_out,
629	                                  args.hybrid_exit_pc, args.vsim_warmup_icount);
630	    }
631	
632	    if (args.cosim_lockstep) {
633	      if (args.elf_file.empty())
634	        throw std::runtime_error("--cosim-lockstep requires a program ELF");
635	      if (!args.resume_from_qemu.empty() || !args.handoff_out.empty()
636	          || args.hybrid_icount || args.hybrid_cosim
