666	        sim.enable_hybrid_cosim(*args.hybrid_cosim);
667	      } else {
668	        sim.enable_hybrid_cosim_targets(
669	          parse_cosim_targets(args.hybrid_cosim_at));
670	      }
671	    }
672	
673	    if (args.kanata_roi)
674	      sim.enable_kanata_roi(args.kanata_file, args.objdump_file,
675	                            args.hybrid_exit_pc);
676	
677	    const int exit_code = sim.run();
678	
679	    sim.cpu.final();
