#include "cpu_config.hpp" // generated by configure in the build tree
#include "hybrid/exit_codes.hpp"
#include "hybrid/state_abi.h"
#include "platform/mmap_backing.hpp"
#include "simulator.hpp"
#include "utils/optparse.hpp"
#include "utils/signals.hpp"
#include "version.hpp"

#include <cci_configuration>
#include <fmt/chrono.h>
#include <fmt/core.h>
#include <spdlog/sinks/stdout_color_sinks.h>
#include <spdlog/spdlog.h>
#include <systemc>

#include <cassert>
#include <csignal>

#include <chrono>
#include <filesystem>
#include <string>
#include <string_view>

// Linker symbols provided config.o, see print_cpu_configuration()
extern char _binary_config_inc_start;
extern char _binary_config_inc_end;

extern "C" const char* get_libaceasim_version() __attribute__((weak));

static void print_cpu_configuration()
{
  // these symbols are defined in obj_sc/config.o
  // they come from andes_ip/kv_core/top/hdl/config.inc
  char* start = &_binary_config_inc_start;
  char* end = &_binary_config_inc_end;
  fwrite(start, 1, end - start, stdout);
}

// Emit the andes-sim engine descriptor (see docs/engine_interface.md). This is
// the self-describe half of the framework's hot-plug contract: andes-sim runs
// `sim_<cfg> --describe`, parses this JSON, and can then drive the binary with
// no per-engine code. vlen/xlen come from the same embedded config.inc blob
// that --print-config dumps; the config name comes from VSIM_CPU_PYMODULE_NAME.
static void describe_engine()
{
  std::string cfg = VSIM_CPU_PYMODULE_NAME;  // "simulator_<cfg>"
  const std::string prefix = "simulator_";
  if (cfg.starts_with(prefix))
    cfg = cfg.substr(prefix.size());

  const std::string_view blob(&_binary_config_inc_start,
                              static_cast<size_t>(&_binary_config_inc_end
                                                  - &_binary_config_inc_start));
  auto scan_int = [blob](std::string_view key) -> long {
    size_t pos = blob.find(key);
    if (pos == std::string_view::npos)
      return 0;
    pos += key.size();
    while (pos < blob.size() && (blob[pos] < '0' || blob[pos] > '9'))
      ++pos;
    long v = 0;
    while (pos < blob.size() && blob[pos] >= '0' && blob[pos] <= '9')
      v = v * 10 + (blob[pos++] - '0');
    return v;
  };
  const long vlen = scan_int("NDS_VLEN");
  const long dlen = scan_int("NDS_DLEN");
  const long elen = scan_int("NDS_ELEN");
  const long xlen = scan_int("NDS_XLEN");

  // Built by hand (not fmt) to keep the literal {bin}/{elf}/{state_in}
  // placeholders out of fmt's brace parser.
  std::string json;
  json += "{\n";
  json += "  \"id\": \"verilator:" + cfg + "\",\n";
  json += "  \"type\": \"verilator\",\n";
  json += "  \"kind\": \"cycle-accurate\",\n";
  json += "  \"vlen\": " + std::to_string(vlen) + ", \"dlen\": "
          + std::to_string(dlen) + ", \"elen\": " + std::to_string(elen)
          + ", \"xlen\": " + std::to_string(xlen) + ",\n";
  json += "  \"triggers\": [\"csr\", \"pc\", \"icount\"],\n";
  json += "  \"roles\": [\"standalone\", \"accurate-leg\"],\n";
  json += "  \"state\": [\"resume\", \"drain\"],\n";
  json += "  \"invoke\": {\n";
  json += "    \"standalone\": [\"{bin}\", \"{elf}\"],\n";
  json += "    \"accurate-leg\": [\"{bin}\", \"{elf}\", "
          "\"--resume-from-qemu\", \"{state_in}\", "
          "\"--handoff-out\", \"{state_out}\", "
          "\"--shared-mem-path\", \"{mmap}\", "
          "\"--shared-mem-size\", \"{mmap_size}\", "
          "\"--shared-mem-base\", \"{mmap_base}\"]\n";
  json += "  },\n";
  json += "  \"result\": \"stderr:cycles\"\n";
  json += "}\n";
  fwrite(json.data(), 1, json.size(), stdout);
}

static void print_version()
{
  fmt::print(
    "Copyright (C) 2013-2026 Andes Technology Corporation. All rights reserved.\n");
  fmt::print("Version : {}\n\n", ANDESCYCLE_VERSION);

  // output ACE, ACERVV support version
  if (get_libaceasim_version)
    fmt::print("Andes Custom Extension : {}\n", get_libaceasim_version());
}

static void print_help()
{
  print_version();
  fmt::print(R"(
Usage: sim_cpu_name [elf_file] [options]

AndesCycle CPU simulator for RISC-V processors

Argument:
  <elf_file>                  RISC-V ELF binary to simulate

General:
  --help, -h                  Print this help message and exit
  --version                   Display version information and exit
  --print-config              Show CPU configuration and exit
  --describe                  Emit the andes-sim engine descriptor (JSON) and exit
  --print-memmap              Show memory map layout and exit
  --log-level <level>         Set logging verbosity [default: 2]
                              (0=trace 1=debug 2=info 3=warn 4=error 5=critical 6=off)

Simulation:
  --mem-latency  <cycles>     Memory access latency in cycles [default: 1]
  --reset-vector <spec>       Set per-hart reset vector
                              <addr>        set all harts to <addr>
                              <hart>:<addr> set specific hart to <addr>
                              Overrides ELF entrypoint if specified

Tracing:
  --pc-trace  <file>          Enable PC trace logging to CSV file
  --kanata    <file>          Enable Kanata pipeline visualization logging
  --clarity   <file>          Enable Clarity pipeline visualization logging
  --objdump   <file>          Load objdump disassembly for pipeline viewer labels
  --kanata-loop-start <pc>    Start PC of the loop body (hex with 0x ok)
  --kanata-loop-end   <pc>    End PC of the loop body. Each retire of this PC
                              counts as one iteration; combine with --kanata or
                              --clarity to dump a steady-state window
  --kanata-loop-skip  <N>     Skip first N iterations [default: 0]
  --kanata-loop-record <X>    Record next X iterations then exit [default: 1]
  --kanata-roi                Auto-derive the kanata window for the hybrid ROI:
                              start_pc = the resumed PC (from
                              --resume-from-qemu state), end_pc = --hybrid-exit-pc
                              (pc-mode) or the unique `csrwi 0x7C0,1` PC
                              scanned from the ELF (csr-mode). Requires
                              --kanata; mutually exclusive with
                              --kanata-loop-*; incompatible with
                              --hybrid-icount.

Debug:
  --jtag-port <port>          JTAG remote bitbang port for OpenOCD [default: 9104]

Extra Options (require additional license):
  --ilm       <image>         Load ILM ROM image
  --dlm       <image>         Load DLM ROM image
  --waveform  <file>          Enable VCD/FST waveform tracing
  --save                      Save context when CPU enters WFI
  --continue                  Restore context and resume execution
  --context-dir <dir>         Context directory [default: ./saved_ctx]

Hybrid (QEMU + Verilator):
  --shared-mem-path <file>    mmap-backed file used as main RAM (zero-copy
                              shared with QEMU). Requires --shared-mem-size.
  --shared-mem-size <bytes>   Size of the shared mmap region; must cover the
                              full main memory range
  --shared-mem-base <hex>     Guest physical address that file offset 0 maps
                              to. Default 0x80000000 (QEMU virt RAM base);
                              override only for non-virt machine types.
  --resume-from-qemu <file>   Resume from a QEMU-side state snapshot.
                              Mutually exclusive with --continue.
  --handoff-out <file>        Drain architectural state to <file> when
                              `csrwi 0x7C0, 1` retires; exit with code 200.
  --hybrid-enter-pc <hex>     PC-trigger mode: orchestrator-side entry PC.
                              Accepted but IGNORED by vsim - entry is QEMU's
                              job (the plugin's `enter_pc=` arg). Logged for
                              symmetry with --hybrid-exit-pc.
  --hybrid-exit-pc <hex>      PC-trigger mode: drain when an insn at this PC
                              retires, instead of pre-scanning the ELF for
                              `csrwi 0x7C0, 1`. The binary need not contain
                              a magic CSR write.
  --hybrid-icount <N>         icount-trigger mode: drain after <N> committed
                              insns retire, regardless of PC. Mutually
                              exclusive with --hybrid-exit-pc and the
                              ELF-scan CSR trigger.
  --hybrid-cosim <N>          checkpoint co-sim: every <N> committed insns,
                              halt, drain a resumable checkpoint appended to
                              the <handoff-out>.ckpts stream, resume.
                              Requires --resume-from-qemu + --handoff-out;
                              incompatible with --hybrid-icount.
  --hybrid-cosim-at <a:b:c>   checkpoint co-sim at explicit ascending retire
                              counts instead of an interval. The LAST target
                              finishes the run (drain + exit) without waiting
                              for the exit trigger. Same requirements as
                              --hybrid-cosim; the two are mutually exclusive.
  --cosim-lockstep            lock-step DV mode: boot the ELF, halt at reset,
                              single-step to the arm pc, then drain one full
                              record per execution attempt to the
                              --cosim-out stream. No QEMU handoff involved;
                              exclusive with all --hybrid-* / --resume-*.
  --cosim-out <file>          REQUIRED with --cosim-lockstep: record stream
                              path (concatenated hybrid_state_v1).
  --cosim-arm-pc <0xADDR>     lock-step arm pc (default: the ELF entry).
  --cosim-max-records <K>     stop after K records (default 0 = run until
                              the program exits via SimControl).
  --vsim-warmup-icount <K>    gem5-style warmup window. Snapshot
                              (mcycle, minstret) K committed insns after vsim
                              entry; the snapshot lands in the drained state
                              file's mcycle_at_measure_start /
                              minstret_at_measure_start so the orchestrator
                              can report cycles excluding the cold-cache
                              prefix. K=0 disables (snapshot fields stay 0).
                              Mode-agnostic: works with csr / pc / icount.
)");
  // --ilm/--dlm: CPU-specific, not all CPUs have ILM/DLM
  // --waveform: requires compile flag VSIMDEBUG
  // --save/--continue/--context-dir: requires compile flag VSIMSAVABLE
}

// cosim_redesign F3: parse the --hybrid-cosim-at colon-separated retire
// targets. Must be strictly ascending, each >= 1.
static auto parse_cosim_targets(const std::string& spec)
  -> std::vector<uint64_t>
{
  std::vector<uint64_t> targets;
  std::size_t pos = 0;
  while (pos <= spec.size()) {
    const auto colon = spec.find(':', pos);
    const auto tok = spec.substr(
      pos, colon == std::string::npos ? std::string::npos : colon - pos);
    try {
      std::size_t used = 0;
      const uint64_t v = std::stoull(tok, &used, 0);
      if (used != tok.size() || v == 0) throw std::invalid_argument(tok);
      targets.push_back(v);
    } catch (...) {
      throw std::runtime_error("--hybrid-cosim-at: bad target '" + tok
                               + "' in '" + spec + "'");
    }
    if (colon == std::string::npos) break;
    pos = colon + 1;
  }
  for (std::size_t i = 1; i < targets.size(); ++i)
    if (targets[i] <= targets[i - 1])
      throw std::runtime_error(
        "--hybrid-cosim-at: targets must be strictly ascending: " + spec);
  return targets;
}

