1	// HandoffController glues CsrTrigger and StateDrain. Given a retired PC,
2	// decides whether to drain state and returns the populated hybrid_state_v1
3	// if so. Pure-logic; no SystemC.
4	
5	#include "hybrid/abstract_command.hpp"
6	#include "hybrid/csr_trigger.hpp"
7	#include "hybrid/handoff_controller.hpp"
8	#include "hybrid/insn_match.h"
9	#include "hybrid/resume_driver.hpp"
10	#include "hybrid/state_abi.h"
11	#include "insn_encoders.hpp"
12	#include "recording_bus.hpp"
13	
14	#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
15	#include <doctest.h>
16	
17	#include <array>
18	#include <cstdint>
19	
20	using hybrid::test::as_bytes;
21	using hybrid::test::encode_slti;
22	using hybrid::test::kDmstatusHaltedAndAcked;
23	using hybrid::test::RecordingBus;
24	using RD = hybrid::ResumeDriver;
25	
26	TEST_CASE("HandoffController: EXIT marker triggers drain and returns state")
27	{
28	  RecordingBus bus;
29	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
30	  bus.regfile[hybrid::regno_gpr(12)] = 3;
31	  bus.regfile[hybrid::regno_csr(RD::kCsrDpc)] = 0x80000004;
32	
33	  hybrid::CsrTrigger trigger;
34	  const std::array<uint32_t, 1> code{encode_slti(0, 0, 0x5A1)};
35	  trigger.scan_buffer(as_bytes(code), /*base_pc=*/0x80000000);
36	
37	  hybrid::HandoffController h(std::move(trigger), bus);
38	  const auto state = h.on_retire(0x80000000);
39	
40	  REQUIRE(state);
41	  CHECK(state->magic == HYBRID_STATE_MAGIC);
42	  CHECK(state->gpr[12] == 3);
43	  CHECK(state->pc == 0x80000004);
44	}
45	
46	TEST_CASE("HandoffController: non-trigger PC returns nullopt without drain")
47	{
48	  RecordingBus bus;
49	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
50	
51	  hybrid::CsrTrigger trigger;
52	  hybrid::HandoffController h(std::move(trigger), bus);
53	
54	  const auto state = h.on_retire(0xDEADBEEF);
55	  CHECK_FALSE(state.has_value());
56	  CHECK(bus.ops.empty());
57	}
58	
59	TEST_CASE("HandoffController: ENTER marker never fires (vsim ignores entry)")
60	{
61	  RecordingBus bus;
62	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
63	
64	  hybrid::CsrTrigger trigger;
65	  const std::array<uint32_t, 1> code{encode_slti(0, 0, 0x5A0)};
66	  trigger.scan_buffer(as_bytes(code), /*base_pc=*/0x80000000);
67	
68	  hybrid::HandoffController h(std::move(trigger), bus);
69	  const auto state = h.on_retire(0x80000000);
70	  CHECK_FALSE(state.has_value());
71	  CHECK(bus.ops.empty());
72	}
73	
74	TEST_CASE("HandoffController: PC-mode synthetic EXIT hit drains like marker EXIT")
75	{
76	  // PC-trigger mode populates the trigger map via add_pc_hit() instead of
77	  // scan_buffer(). HandoffController must dispatch on `kind` only and not
78	  // depend on a recorded `insn`. This is the single-test contract the PC
79	  // mode relies on.
80	  RecordingBus bus;
81	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
82	  bus.regfile[hybrid::regno_gpr(12)] = 7;
83	  bus.regfile[hybrid::regno_csr(RD::kCsrDpc)] = 0x80000048;
84	
85	  hybrid::CsrTrigger trigger;
86	  trigger.add_pc_hit(0x80000044, HYBRID_HANDOFF_EXIT);
87	
88	  hybrid::HandoffController h(std::move(trigger), bus);
89	  const auto state = h.on_retire(0x80000044);
90	
91	  REQUIRE(state);
92	  CHECK(state->magic == HYBRID_STATE_MAGIC);
93	  CHECK(state->gpr[12] == 7);
94	  CHECK(state->pc == 0x80000048);
95	}
96	
97	TEST_CASE("HandoffController: PC-mode hit at unrelated PC stays silent")
98	{
99	  RecordingBus bus;
100	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
101	
102	  hybrid::CsrTrigger trigger;
103	  trigger.add_pc_hit(0x80000044, HYBRID_HANDOFF_EXIT);
104	
105	  hybrid::HandoffController h(std::move(trigger), bus);
106	  const auto state = h.on_retire(0x80000048);
107	  CHECK_FALSE(state.has_value());
108	  CHECK(bus.ops.empty());
109	}
110	
111	// ---- cosim checkpoints (cosim_roi F2) ----
112	
113	TEST_CASE("HandoffController cosim: sink fires every N retires with a "
114	          "resumable drain, k counts from 1")
115	{
116	  RecordingBus bus;
117	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
118	  bus.regfile[hybrid::regno_gpr(12)] = 42;
119	  bus.regfile[hybrid::regno_csr(RD::kCsrDpc)] = 0x80000010;
120	
121	  hybrid::CsrTrigger trigger;  // no EXIT anywhere
122	  hybrid::HandoffController h(std::move(trigger), bus);
123	
124	  hybrid_state_v1 input{};
125	  input.magic   = HYBRID_STATE_MAGIC;
126	  input.version = HYBRID_STATE_VERSION;
127	  input.flags   = HYBRID_FLAG_RV64;
128	  input.priv    = 3;
129	  h.set_passthrough_input(input);
130	
131	  std::vector<uint64_t> ks;
132	  std::vector<uint64_t> pcs;
133	  std::vector<uint64_t> x12s;
134	  h.enable_cosim(3, [&](const hybrid_state_v1& st, uint64_t k) {
135	    ks.push_back(k);
136	    pcs.push_back(st.pc);
137	    x12s.push_back(st.gpr[12]);
138	  });
139	
140	  for (int i = 0; i < 7; ++i) {
141	    const auto state = h.on_retire(0x1000 + 4u * static_cast<unsigned>(i));
142	    CHECK_FALSE(state.has_value());
143	  }
144	
145	  // Checkpoints at retires 3 and 6 (7th retire is below the next target).
146	  REQUIRE(ks.size() == 2);
147	  CHECK(ks[0] == 1u);
148	  CHECK(ks[1] == 2u);
149	  CHECK(pcs[0] == 0x80000010u);
150	  CHECK(x12s[0] == 42u);
151	
152	  // Each checkpoint resumed the hart afterwards.
153	  std::size_t resumes = 0;
154	  for (const auto& op : bus.ops) {
155	    const bool resume_write = op.kind == hybrid::test::DmiOp::Kind::Write
156	      && op.reg == RD::kDmcontrol
157	      && (op.value & RD::kDmcontrolResumereq) != 0u;
158	    if (resume_write) ++resumes;
159	  }
160	  CHECK(resumes == 2u);
161	}
162	
163	TEST_CASE("HandoffController cosim: EXIT wins on the same retire -- final "
164	          "drain returned, sink not invoked")
165	{
166	  RecordingBus bus;
167	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
168	  bus.regfile[hybrid::regno_csr(RD::kCsrDpc)] = 0x80000048;
169	
170	  hybrid::CsrTrigger trigger;
171	  trigger.add_pc_hit(0x80000044, HYBRID_HANDOFF_EXIT);
172	
173	  hybrid::HandoffController h(std::move(trigger), bus);
174	
175	  hybrid_state_v1 input{};
176	  input.magic   = HYBRID_STATE_MAGIC;
177	  input.version = HYBRID_STATE_VERSION;
178	  input.flags   = HYBRID_FLAG_RV64;
179	  input.priv    = 3;
180	  h.set_passthrough_input(input);
181	
182	  std::size_t sink_calls = 0;
183	  h.enable_cosim(1, [&](const hybrid_state_v1&, uint64_t) { ++sink_calls; });
184	
185	  const auto state = h.on_retire(0x80000044);
186	  REQUIRE(state.has_value());
187	  CHECK(sink_calls == 0u);
188	}
189	
190	TEST_CASE("HandoffController cosim: checkpoint without the passthrough "
191	          "snapshot throws")
192	{
193	  RecordingBus bus;
194	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
195	
196	  hybrid::CsrTrigger trigger;
197	  hybrid::HandoffController h(std::move(trigger), bus);
198	  h.enable_cosim(1, [](const hybrid_state_v1&, uint64_t) {});
199	
200	  CHECK_THROWS_AS((void) h.on_retire(0x1000), std::runtime_error);
201	}
202	
203	// ---- cosim explicit targets (cosim_redesign F3) ----
204	
205	TEST_CASE("HandoffController cosim targets: sink fires at each target; the "
206	          "LAST target finishes the run instead of resuming")
207	{
208	  RecordingBus bus;
209	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
210	  bus.regfile[hybrid::regno_gpr(12)] = 42;
211	  bus.regfile[hybrid::regno_csr(RD::kCsrDpc)] = 0x80000010;
212	
213	  hybrid::CsrTrigger trigger;  // no EXIT anywhere
214	  hybrid::HandoffController h(std::move(trigger), bus);
215	
216	  hybrid_state_v1 input{};
217	  input.magic   = HYBRID_STATE_MAGIC;
218	  input.version = HYBRID_STATE_VERSION;
219	  input.flags   = HYBRID_FLAG_RV64;
220	  input.priv    = 3;
221	  h.set_passthrough_input(input);
222	
223	  std::vector<uint64_t> ks;
224	  h.enable_cosim_targets({2, 5}, [&](const hybrid_state_v1& st, uint64_t k) {
225	    ks.push_back(k);
226	    CHECK(st.gpr[12] == 42u);
227	  });
228	
229	  // Retires 1..4: no exit. Target 2 drains checkpoint 1 and resumes.
230	  for (int i = 0; i < 4; ++i)
231	    CHECK_FALSE(h.on_retire(0x1000 + 4u * static_cast<unsigned>(i)).has_value());
232	
233	  // Retire 5 = last target: record 2 goes to the sink AND the run finishes
234	  // (state returned; simulator writes <handoff_out> and exits 200).
235	  const auto final_state = h.on_retire(0x1010);
236	  REQUIRE(final_state.has_value());
237	  CHECK(final_state->gpr[12] == 42u);
238	
239	  REQUIRE(ks.size() == 2);
240	  CHECK(ks[0] == 1u);
241	  CHECK(ks[1] == 2u);
242	
243	  // Only the FIRST checkpoint resumed the hart; the final drain leaves it
244	  // halted (the run ends there).
245	  std::size_t resumes = 0;
246	  for (const auto& op : bus.ops) {
