262	static uint64_t read_reg64(struct qemu_plugin_register *h)
263	{
264	    if (!h) return 0;
265	    g_autoptr(GByteArray) buf = g_byte_array_new();
266	    int sz = qemu_plugin_read_register(h, buf);
267	    if (sz <= 0) return 0;
268	    uint64_t v = 0;
269	    memcpy(&v, buf->data, sz < 8 ? (size_t) sz : 8);
270	    return v;
271	}
