1	// `andesim run --mode fast|cycle|hybrid [engine selection] ELF [-- engine args]`.
2	//
3	// The top selection axis. F7/F8 land the two standalone models, `fast` (QEMU)
4	// and `cycle` (a cycle-accurate engine, from reset): each resolves its
5	// engine, then hands off to transparent passthrough -- the ELF plus everything
6	// after `--` becomes the engine's own command line, run with inherited stdio,
7	// no timeout, and the exit code propagated, so a gdbstub / monitor /
8	// semihosting console all behave as if the engine were invoked directly.
9	// `hybrid` (F9) orchestrates a QEMU1 -> vsim handoff via run_plan and prints the
10	// window-cycle figure (the vsim mcycle delta).
11	#include <algorithm>
12	#include <chrono>
13	#include <cstdint>
14	#include <cstdio>
15	#include <cstdlib>
16	#include <filesystem>
17	#include <optional>
18	#include <string>
19	#include <thread>
20	#include <vector>
21	
22	#include "argv.hpp"
23	#include "cli.hpp"
24	#include "cosim_lockstep.hpp"
25	#include "elf_syms.hpp"
26	#include "engine_descriptor.hpp"
27	#include "engine_registry.hpp"
28	#include "hybrid.hpp"
29	#include "hybrid/state_abi.h"  // HYBRID_V_SCRATCH_BYTES (L26/F3 overlap check)
30	#include "models.hpp"
31	#include "plan.hpp"
32	#include "process.hpp"
33	#include "repo_root.hpp"
34	#include "run_passthrough.hpp"
35	#include "run_plan.hpp"
36	#include "shm.hpp"
37	#include "state.hpp"
38	#include "state_diff.hpp"
39	
40	namespace fs = std::filesystem;
41	
42	namespace andes_sim {
43	namespace {
44	
45	// Resolve `path` to an absolute path. Returns the resolved string on success;
46	// on failure prints an error tagged with `ctx` and returns "".
47	std::string abs_elf(const std::string& path, const std::string& ctx) {
48	  std::error_code ec;
49	  std::string abs = fs::absolute(path, ec).string();
50	  if (ec) {
51	    std::fprintf(stderr, "andesim run %s: cannot resolve ELF '%s'\n",
52	                 ctx.c_str(), path.c_str());
53	    return "";
54	  }
55	  return abs;
56	}
57	
58	// Validate the lone-ELF positional shape the standalone models require: print
59	// the diagnostic and return 2 on a violation, else 0. Split out so `cycle`
60	// can reject a missing/extra ELF BEFORE paying for engine discovery (which
61	// spawns a --describe subprocess per Verilator build). `model` labels the error.
62	int check_one_elf(const Cli& cli, const char* model) {
63	  if (cli.positional.empty()) {
64	    std::fprintf(stderr,
65	                 "andesim run --mode %s: missing ELF (the workload to run; "
66	                 "e.g. a tests/fixtures/<name>.elf)\n",
67	                 model);
68	    return 2;
69	  }
70	  if (cli.positional.size() > 1) {
71	    std::fprintf(stderr,
72	                 "andesim run --mode %s: unexpected argument '%s' "
73	                 "(engine args go after --)\n",
74	                 model, cli.positional[1].c_str());
75	    return 2;
76	  }
77	  return 0;
78	}
79	
80	// The standalone-passthrough spine shared by `fast` and `cycle`: both take a
81	// single ELF, then exec the resolved engine standalone with `extra` (model
82	// flags the framework forwards, e.g. fast's -m) followed by the post-`--`
83	// args verbatim (inherit stdio, no timeout, propagate exit code). The only
84	// per-model differences -- which engine, and how it is selected -- are resolved
85	// by the caller; `model` here only labels the positional diagnostics.
86	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
87	                   const char* model,
88	                   const std::vector<std::string>& extra = {}) {
89	  if (int rc = check_one_elf(cli, model)) return rc;
90	  // QEMU's -bios flag searches its data directory for relative paths rather
91	  // than the CWD; resolve to absolute so both QEMU and vsim find the ELF.
92	  const std::string elf = abs_elf(cli.positional[0], "--mode " + std::string(model));
93	  if (elf.empty()) return 2;
94	  std::vector<std::string> args = extra;
95	  args.insert(args.end(), cli.passthrough.begin(), cli.passthrough.end());
96	  std::string err;
97	  int rc = run_passthrough(eng, "standalone", elf, args, err);
98	  if (!err.empty()) std::fprintf(stderr, "andesim run: %s\n", err.c_str());
99	  return rc;
100	}
101	
102	// `run --mode fast`: QEMU alone, functional, transparent passthrough. Needs
103	// only the built-in qemu descriptor, so it resolves that directly rather than
104	// discover_engines(), which would spawn a --describe subprocess per Verilator
105	// build only to discard them all here.
106	int run_fast(const Cli& cli) {
107	  // fast is QEMU-only; an explicit engine must name it.
108	  if (!cli.engine.empty() && cli.engine != "qemu") {
109	    std::fprintf(stderr,
110	                 "andesim run --mode fast: engine must be 'qemu', got '%s'\n",
111	                 cli.engine.c_str());
112	    return 2;
113	  }
114	  // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
115	  // default injected). It precedes the post-`--` args, so a user's own -m wins.
116	  std::string err;
117	  std::vector<std::string> extra = qemu_m_args(cli.mem_size, err);
118	  if (!err.empty()) {
119	    std::fprintf(stderr, "andesim run --mode fast: %s\n", err.c_str());
120	    return 2;
121	  }
122	  // --gdb: inject QEMU's built-in GDB stub and pause at startup.
123	  if (cli.gdb) {
124	    const std::string port = cli.gdb_port.empty() ? "1234" : cli.gdb_port;
125	    extra.push_back("-gdb");
126	    extra.push_back("tcp::" + port);
127	    extra.push_back("-S");
128	  }
129	  return run_standalone(cli, builtin_qemu(), "fast", extra);
130	}
