int cmd_run(const Cli& cli) {
  if (cli.model.empty()) {
    std::fprintf(stderr,
                 "andesim run: --mode fast|cycle|hybrid is required "
                 "(pick the composition; see 'andesim run --help')\n");
    return 2;
  }
  if (!find_model(cli.model)) {
    std::fprintf(stderr,
                 "andesim run: unknown model '%s' (want fast|cycle|hybrid)\n",
                 cli.model.c_str());
    return 2;
  }
  if (!cli.gdb_port.empty() && !cli.gdb) {
    std::fprintf(stderr, "andesim run: --gdb-port requires --gdb\n");
    return 2;
  }
  // --gdb is an interactive debugging aid; the hybrid handoff runs QEMU1 then
  // vsim sequentially in a pipeline and cannot pause for a debugger to attach.
  if (cli.gdb && cli.model == "hybrid") {
    std::fprintf(stderr,
                 "andesim run: --gdb is not supported with --mode hybrid\n");
    return 2;
  }
  // --verify re-runs the workload against a QEMU oracle -- only the hybrid
  // composition has a second engine to check.
  if (cli.verify && cli.model != "hybrid") {
    std::fprintf(stderr,
                 "andesim run: --verify requires --mode hybrid (the %s "
                 "model has nothing to cross-check)\n",
                 cli.model.c_str());
    return 2;
  }
  // --cosim cross-checks against a QEMU oracle: hybrid (ROI window checkpoints)
  // or cycle (lock-step from reset). The fast model is QEMU itself -- nothing
  // to check.
  if (cli.cosim && cli.model == "fast") {
    std::fprintf(stderr,
                 "andesim run: --cosim requires --mode hybrid or cycle "
                 "(fast is QEMU itself, nothing to cross-check)\n");
    return 2;
  }
  if (cli.cosim && cli.verify) {
    std::fprintf(stderr,
                 "andesim run: --verify and --cosim are exclusive (--cosim "
                 "already cross-checks the final state)\n");
    return 2;
  }
  // --cosim-interval is the hybrid ROI knob; --cosim-max-records is the
  // cycle lock-step knob. Each requires --cosim and its own model.
  if (!cli.cosim && !cli.cosim_interval.empty()) {
    std::fprintf(stderr, "andesim run: --cosim-interval requires --cosim\n");
    return 2;
  }
  if (!cli.cosim_interval.empty() && cli.model != "hybrid") {
    std::fprintf(stderr,
                 "andesim run: --cosim-interval applies to --mode hybrid "
                 "(cycle lock-step uses --cosim-max-records)\n");
    return 2;
  }
  if (!cli.cosim_max_records.empty() && !(cli.cosim && cli.model == "cycle")) {
    std::fprintf(stderr,
                 "andesim run: --cosim-max-records requires --mode cycle "
                 "--cosim (lock-step)\n");
    return 2;
  }
  // --cosim-refine narrows the hybrid ROI window; it has no meaning for the
  // cycle lock-step (already exact) or without --cosim.
  if (cli.cosim_refine && !(cli.cosim && cli.model == "hybrid")) {
    std::fprintf(stderr,
                 "andesim run: --cosim-refine requires --mode hybrid "
                 "--cosim (cycle lock-step is already instruction-exact)\n");
    return 2;
  }
  // --trigger / --pc-start / --pc-end delimit the hybrid ROI window; fast and
  // cycle run the whole program and would silently drop them, handing back a
  // whole-program figure for the window the user asked for. Reject instead.
  // Exception: --pc-start doubles as the cycle lock-step arm pc under
  // --mode cycle --cosim (run_cosim_lockstep), so it stays valid there.
  if (!cli.trigger.empty() && cli.model != "hybrid") {
    std::fprintf(stderr,
                 "andesim run: --trigger applies only to --mode hybrid "
                 "(the ROI delimiter); fast/cycle run the whole program\n");
    return 2;
  }
  if (!cli.pc_end.empty() && cli.model != "hybrid") {
    std::fprintf(stderr,
                 "andesim run: --pc-end applies only to --mode hybrid "
                 "--trigger pc\n");
    return 2;
  }
  if (!cli.pc_start.empty() && cli.model != "hybrid" &&
      !(cli.model == "cycle" && cli.cosim)) {
    std::fprintf(stderr,
                 "andesim run: --pc-start applies only to --mode hybrid "
                 "--trigger pc (or --mode cycle --cosim)\n");
    return 2;
  }
  if (cli.model == "fast") return run_fast(cli);
  if (cli.model == "cycle") return run_accurate(cli);
  return run_hybrid(cli);  // model validated above; only hybrid remains
}

